// ============================================================
// CC NOTIFY — [1] render + resolve config
//
// Reads the subflow env config, renders {{field}} templates
// against the endpoint's data, and normalises targeting into
// the SQL fragments the resolve step needs.
//
// No SQL is built here. This node emits params + fragments only.
// ============================================================

// ── CONFIG ───────────────────────────────────────────────────
const recipientMode   = env.get('recipientMode')  || 'role';    // role | user | all
const recipientValue  = env.get('recipientValue') || '';        // "billing,coordinator"
const recipientPath   = env.get('recipientPath')  || '';        // msg path, overrides value
const dataRootPath    = env.get('dataRoot')       || 'payload';
const titleTemplate   = env.get('titleTemplate')  || 'Notification';
const bodyTemplate    = env.get('bodyTemplate')   || '';
const urlTemplate     = env.get('url')            || './home';
const notificationTag = env.get('tag')            || 'notification';

// Ledger toggle. Default is to save — skipping is the deliberate
// exception, so an unset env var must never silently drop the row.
const saveToInbox     = (env.get('saveToInbox') || 'y') !== 'n';

// ── HELPERS ──────────────────────────────────────────────────

// Walk a dotted path: getValueAtPath(msg, 'ctx.req') -> msg.ctx.req
// Returns undefined (never throws) if any link is missing.
function getValueAtPath(sourceObject, dottedPath) {
  const pathSegments = String(dottedPath || '').split('.');
  return pathSegments.reduce(
    (currentValue, segment) =>
      (currentValue == null ? undefined : currentValue[segment]),
    sourceObject
  );
}

// "Card {{pcn}}" -> "Card PCN-12345". Missing fields render empty.
function renderTemplate(templateString, sourceData) {
  const PLACEHOLDER_PATTERN = /{{\s*([\w.]+)\s*}}/g;
  return String(templateString || '').replace(
    PLACEHOLDER_PATTERN,
    (fullMatch, fieldName) => {
      const fieldValue = getValueAtPath(sourceData, fieldName);
      return fieldValue == null ? '' : fieldValue;
    }
  );
}

// "alice, bob" -> ['alice','bob']   (blanks dropped)
function splitCommaList(commaSeparatedString) {
  return String(commaSeparatedString || '')
    .split(',')
    .map(item => item.trim())
    .filter(Boolean);
}

// Accepts ['a','b'] or "a,b" or "a" — all become ['a', ...].
function toRecipientList(rawValue) {
  if (Array.isArray(rawValue)) {
    return rawValue.map(item => String(item).trim()).filter(Boolean);
  }
  return splitCommaList(rawValue);
}

// ── DATA SOURCE FOR TEMPLATES ────────────────────────────────
// Deliberately independent of the recipient — record data and
// recipients come from different places.
const templateData = getValueAtPath(msg, dataRootPath) || {};

// ── RESOLVE RECIPIENTS ───────────────────────────────────────
// Static env value unless recipientPath is configured. An empty
// dynamic lookup DROPS the message rather than falling back to
// the static value — notifying the wrong people is worse than
// notifying nobody.
let resolvedRecipients;

if (recipientPath) {
  resolvedRecipients = toRecipientList(getValueAtPath(msg, recipientPath));

  if (resolvedRecipients.length === 0) {
    node.warn(
      `CC NOTIFY: recipientPath "${recipientPath}" resolved empty — ` +
      `dropping "${titleTemplate}". Check the lookup upstream.`
    );
    return null;
  }
} else {
  resolvedRecipients = splitCommaList(recipientValue);
}

// ── RENDER ONCE ──────────────────────────────────────────────
// Both the ledger and the push read from this. Rendering once is
// what stops the saved row and the delivered push disagreeing.
msg.notif = {
  title: renderTemplate(titleTemplate, templateData),
  body:  renderTemplate(bodyTemplate,  templateData),
  url:   renderTemplate(urlTemplate,   templateData),
  tag:   renderTemplate(notificationTag, templateData)
};

// ── SHAPE THE TARGETING ──────────────────────────────────────
// Emits the WHERE fragment + params for step [3]. The `u.` alias
// is baked into roleClause, so the resolve SELECTs must alias
// the user table as `u`.
if (recipientMode === 'user') {
  if (resolvedRecipients.length === 0) {
    node.warn(`CC NOTIFY: no usernames for "${titleTemplate}" — dropping.`);
    return null;
  }
  msg.placeholders = resolvedRecipients.map(() => '?').join(',');
  msg.payload = resolvedRecipients;
}
else if (recipientMode === 'role') {
  if (resolvedRecipients.length === 0) {
    node.warn(`CC NOTIFY: no roles for "${titleTemplate}" — dropping.`);
    return null;
  }
  msg.roleClause = resolvedRecipients
    .map(() => 'JSON_CONTAINS(u.userrole, JSON_QUOTE(?))')
    .join(' OR ');
  msg.payload = resolvedRecipients;
}
else if (recipientMode === 'all') {
  msg.payload = [];
}
else {
  node.warn(`CC NOTIFY: unknown recipientMode "${recipientMode}" — dropping.`);
  return null;
}

msg.selectMode  = recipientMode;

// Carried on the message rather than read again downstream: a switch node
// reading env would work, but this way the decision shows up in a debug
// dump, which matters when someone asks why a notification never appeared
// in the panel.
msg.saveToInbox = saveToInbox;

// ── STRIP HTTP CONTEXT (fire-and-forget) ─────────────────────
// The endpoint already sent its response. If msg.res survived,
// anything downstream could fire a second one.
delete msg.req;
delete msg.res;
delete msg.statusCode;

return msg;

