// ============================================================
// CC NOTIFY — [4] extract userids
//
// Runs on BOTH branches, before the saveToInbox switch.
// Resolution happens ONCE and feeds both the ledger and the push,
// so the two can never disagree about who the recipients were.
// ============================================================

const rows = msg.payload;

if (!Array.isArray(rows) || rows.length === 0) {
  node.warn(
    `CC NOTIFY: no active users matched mode "${msg.selectMode}" — ` +
    `nothing saved, nothing sent for "${msg.notif.title}".`
  );
  return null;
}

// Kept on the message so step [7] can reuse them for the
// subscription lookup. One resolution, two consumers.
msg.userIds = rows.map(row => row.recid).filter(id => id != null);

if (msg.userIds.length === 0) {
  node.warn('CC NOTIFY: resolve returned rows but no recid values — dropping.');
  return null;
}

return msg;

// ============================================================
// CC NOTIFY — [6] build ledger rows
//
// Skipped entirely when saveToInbox is off. Params only — the SQL
// lives in the next template node.
// ============================================================

const n = msg.notif;

// (?,?,?,?,?),(?,?,?,?,?)...  one group per user.
// The empty guard in [4] matters here: "VALUES ;" is a syntax error.
msg.rowPlaceholders = msg.userIds.map(() => '(?,?,?,?,?)').join(',');

msg.payload = msg.userIds.reduce(
  (params, userId) => params.concat([
    userId, n.title, n.body, n.url, n.tag
  ]),
  []
);

return msg;

