// ============================================================
// CC NOTIFY — [7] subscription lookup params
//
// Both branches land here. If the ledger was written, everything
// from this point is best-effort — push can fail entirely and the
// user still sees the notification when they open the app.
//
// Because step [4] already resolved userids, this is ONE query
// with no user-table join and no role clause.
// ============================================================

msg.placeholders = msg.userIds.map(() => '?').join(',');
msg.payload = msg.userIds;

return msg;

// ============================================================
// CC NOTIFY — [9] shape subscriptions for web-push
// ============================================================

const rows = msg.payload;

if (!Array.isArray(rows) || rows.length === 0) {
  // Not an error. If the ledger ran, this is exactly the case it
  // exists for — saved, but nobody has a live device.
  node.warn(
    `CC NOTIFY: "${msg.notif.title}" resolved to ${msg.userIds.length} user(s), ` +
    `but no active subscriptions — no push sent.`
  );
  return null;
}

msg.subscriptions = rows.map(row => {
  const sub = typeof row.subscription === 'string'
    ? JSON.parse(row.subscription)
    : row.subscription;
  return {
    endpoint: sub.endpoint,
    keys: { p256dh: sub.keys.p256dh, auth: sub.keys.auth }
  };
});

msg.notification = {
  title: msg.notif.title || 'Notification',
  body:  msg.notif.body  || '',
  url:   msg.notif.url   || './home',
  tag:   msg.notif.tag   || 'notification'
};

return msg;

// ============================================================
// CC NOTIFY — [11] deactivate dead endpoints
// ============================================================

const failedList = msg.payload.failed || [];
if (failedList.length === 0) return null;

const sentEndpoints = new Set(
  (msg.payload.sent || []).map(s => s.endpoint).filter(Boolean)
);

const deadEndpoints = (msg.subscriptions || [])
  .map(s => s.endpoint)
  .filter(ep => ep && !sentEndpoints.has(ep));

// If the diff doesn't match the failure count, our assumption that
// sent/failed are disjoint subsets is wrong. Bail rather than
// deactivate the wrong rows.
if (deadEndpoints.length !== failedList.length) {
  node.warn(
    `CC NOTIFY: endpoint diff mismatch — ${deadEndpoints.length} unaccounted ` +
    `vs ${failedList.length} failed. Not deactivating.`
  );
  return null;
}

node.warn(`CC NOTIFY: deactivating ${deadEndpoints.length} dead subscription(s).`);

msg.placeholders = deadEndpoints.map(() => '?').join(',');
msg.payload = deadEndpoints;
return msg;

