    userAgent:    msg.req?.headers?.['user-agent'] || null,
};

// --------------------------------------------------
// 6. Respond — fetch vs browser
// --------------------------------------------------
if (isFetchRequest) {
    msg.statusCode = 403;
    msg.payload    = {
        success: false,
        message: 'You do not have permission to access this resource.'
    };
    return [null, msg, null];        // Output 2
}

msg.statusCode = 302;
msg.headers    = { Location: './unauthorized' };
msg.payload    = 'Redirecting...';
