// ===== Auth Middleware =====
// Outputs:
//   1 → Form redirect (302)       → wire to http response
//   2 → Fetch denied (401 JSON)   → wire to http response
//   3 → Authenticated             → go to RBAC / business logic

// --------------------------------------------------
// GET TOKENS FROM COOKIES
// --------------------------------------------------
const loginToken = msg.req?.cookies?.loginToken;
const pinToken   = msg.req?.cookies?.pinToken;

const loginTokenMap = global.get('loginTokenMap') || new Map();
const pinTokenMap   = global.get('pinTokenMap')   || new Map();

const currentPath = msg.req?.url;

// --------------------------------------------------
// Detect Fetch / API Request
// --------------------------------------------------
const isFetchRequest =
    msg.req?.headers?.['x-requested-with'] === 'XMLHttpRequest' ||
    msg.req?.headers?.accept?.includes('application/json');

msg.isFetchRequest = isFetchRequest;

// --------------------------------------------------
// INITIALIZE
// --------------------------------------------------
let userDetails = null;
let redirectTo  = null;

// --------------------------------------------------
// VALIDATE TOKENS
// --------------------------------------------------
const loginData = loginToken ? loginTokenMap.get(loginToken) : null;
const pinData   = pinToken   ? pinTokenMap.get(pinToken)     : null;

// ==================================================
// AUTH LOGIC
// ==================================================

/* 1. FULL LOGIN */
if (loginData) {
    userDetails = loginData;
    if (currentPath === '/login' || currentPath === '/pin') {
        redirectTo = '/home';
    }
}

/* 2. PIN EXISTS — NOT FULLY LOGGED IN */
else if (pinData) {
    if (currentPath === '/login' || currentPath === '/pin') {
        // Allow through — Output 3
        return [null, null, msg];
    }
    redirectTo = '/pin';
}

/* 3. NO TOKENS */
else {
    if (currentPath === '/login') {
        return [null, null, msg];
    }
    redirectTo = currentPath === '/pin' ? '/login' : '/login';
}

// ==================================================
// HANDLE REDIRECT
// ==================================================
if (redirectTo) {

    if (userDetails) {
        msg.userDetails   = userDetails;
        msg.isAuthenticated = true;
    }

    if (isFetchRequest) {
        // Output 2 → Fetch denied
        msg.statusCode = 401;
        msg.payload = {
            success:  false,
            message:  'Authentication required',
            redirect:'.' + redirectTo
        };
        return [null, msg, null];
    } else {
        // Output 1 → Form/browser redirect
        msg.statusCode = 302;
        msg.headers    = { Location: '.' + redirectTo };
        msg.payload    = 'Redirecting...';
        return [msg, null, null];
    }
}

// ==================================================
// AUTH SUCCESS — Output 3
// ==================================================
if (userDetails) {
    msg.userDetails     = userDetails;
    msg.isAuthenticated = true;
    return [null, null, msg];
}

