const pinData = pinToken ? pinTokenMap.get(pinToken) : null;


// ==================================================
// ================= AUTH LOGIC =====================
// ==================================================

/* ==================================================
   1️⃣ FULL LOGIN (loginToken valid)
================================================== */
if (loginData) {

    userDetails = loginData;

    // If logged in & hitting login or pin → redirect to home
    if (currentPath === "/login" || currentPath === "/pin") {
        redirectTo = "/home";
    }
}


/* ==================================================
   2️⃣ PIN EXISTS BUT NOT FULLY LOGGED IN
================================================== */
else if (pinData) {

    // Allow login page
    if (currentPath === "/login") {
        return [null, null, msg];
    }

    // Allow pin page
    if (currentPath === "/pin") {
        return [null, null, msg];
    }

    // Any other page → redirect to pin
    redirectTo = "/pin";
}


/* ==================================================
   3️⃣ NO TOKENS
================================================== */
else {

    // Allow login page
    if (currentPath === "/login") {
        return [null, null, msg];
    }

    // If accessing pin page without pinToken → go to login
    if (currentPath === "/pin") {
        redirectTo = "/login";
    }

    // Any other page → redirect to login
    else {
        redirectTo = "/login";
    }
}


// ==================================================
// =============== HANDLE REDIRECT ==================
// ==================================================

if (redirectTo) {

    // 🔥 IMPORTANT FIX:
    // If user is logged in, attach details BEFORE redirect
    if (userDetails) {
        msg.userDetails = userDetails;
        msg.isAuthenticated = true;
    }

    if (isFetchRequest) {
