    // Success response
    msg.statusCode = 200;

    msg.payload = {
        success: true,
        message: "SOS Alert Saved Successfully"
    };

} catch (err) {

    // Error response
    msg.statusCode = 500;

    msg.payload = {
        success: false,
        message: "Failed to save SOS Alert",
        error: err.message
    };

    node.error("SOS Alert Error: " + err.message, msg);
}

return msg;

const category = String(msg.req?.query?.category || '').trim();

msg.sosCategory = category;

if (!category) {

    msg.topic = `
        SELECT DISTINCT category
        FROM sosalerts
        WHERE category IS NOT NULL
          AND TRIM(category) <> ''
          AND active = 'y'
        ORDER BY category ASC;
    `;

    msg.payload = [];

} else {

    msg.topic = `
        SELECT
            recid,
            category,
            alert
        FROM sosalerts
        WHERE category = ?
          AND alert IS NOT NULL
          AND TRIM(alert) <> ''
          AND active = 'y'
        ORDER BY alert ASC;
    `;

    msg.payload = [category];
}

return msg;

msg.statusCode = 200;

const rows = Array.isArray(msg.payload) ? msg.payload : [];

if (!msg.sosCategory) {

    msg.payload = {
        success: true,
        categories: rows
    };

} else {

    msg.payload = {
        success: true,
        category: msg.sosCategory,
        alerts: rows
    };

}

return msg;

